// Tests for mep's in-house .blend reader (blend_file.h / blend_scene.h)
// and the zstd decoder it uses for compressed .blend files
// (zstd_decode.h). Pure CPU, no gfx backend.
//
// Fixtures (test/fixtures/, see SOURCES.txt there):
//   zstd/*.zst   -- MakeZstdTestData() output compressed by the reference
//                   `zstd` CLI at several levels/options; each must decode
//                   back to exactly the generated bytes.
//   blend/*.blend -- real files saved by Blender 2.48, 2.79, 3.3, 4.0 and
//                   5.0 (uncompressed, gzip and zstd containers, 4- and
//                   8-byte pointers). Expected transforms of the pre-5.0
//                   files were cross-checked against the world matrices
//                   Blender itself stored in them (Object.obmat).

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <string>
#include <vector>

#include "blend_file.h"
#include "blend_scene.h"
#include "zstd_decode.h"

#ifndef MEP_SOURCE_DIR
#define MEP_SOURCE_DIR "."
#endif

namespace {

int g_failures = 0;

void Check(bool condition, const char *expression, int line) {
    if (condition) return;
    std::fprintf(stderr, "CHECK FAILED: %s at %s:%d\n", expression, __FILE__, line);
    g_failures++;
}
#define CHECK(condition) Check((condition), #condition, __LINE__)

std::string Fixture(const std::string &rel) { return std::string(MEP_SOURCE_DIR) + "/test/fixtures/" + rel; }

std::string ReadFile(const std::string &path) {
    std::ifstream in(path, std::ios::binary);
    return std::string((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
}

// Deterministic test data; the committed .zst fixtures are this output
// compressed by the zstd CLI. kind 0: word text, 1: skewed bytes (good
// for Huffman/FSE), 2: incompressible bytes (raw blocks), 3: long runs
// (RLE blocks, long matches).
std::string MakeZstdTestData(int kind, size_t n) {
    uint32_t s = 0x12345678u + static_cast<uint32_t>(kind);
    auto next = [&] {
        s = s * 1664525u + 1013904223u;
        return s >> 8;
    };
    static const char *kWords[] = {"alpha ", "beta ", "gamma ", "delta\n", "x ", "yy ", "zzz ", "{ ", "} ", "the quick brown fox "};
    std::string out;
    while (out.size() < n) {
        if (kind == 0) {
            out += kWords[next() % 10];
        } else if (kind == 1) {
            uint32_t r = next() % 8;
            out += static_cast<char>(r < 4 ? 0 : r < 6 ? 1 : r == 6 ? 255 : (next() & 255));
        } else if (kind == 2) {
            out += static_cast<char>(next() & 255);
        } else {
            size_t len = 1000 + next() % 5000;
            out += std::string(len, static_cast<char>('a' + next() % 3));
        }
    }
    out.resize(n);
    return out;
}

bool Decode(const std::string &in, std::string *out, std::string *error = nullptr) {
    out->clear();
    return zstd::Decompress(reinterpret_cast<const unsigned char *>(in.data()), in.size(), *out, error);
}

void TestZstd() {
    // XXH64 reference vectors.
    CHECK(zstd::Xxh64(reinterpret_cast<const unsigned char *>(""), 0, 0) == 0xEF46DB3751D8E999ull);
    CHECK(zstd::Xxh64(reinterpret_cast<const unsigned char *>("abc"), 3, 0) == 0x44BC2CF5AD770999ull);

    struct Case {
        const char *file;
        int kind;
        size_t size;
    };
    const Case cases[] = {
        {"zstd/text_l1.zst", 0, 100000},          {"zstd/text_l19_check.zst", 0, 100000},
        {"zstd/text_l22.zst", 0, 100000},         {"zstd/text_l6_smallblocks.zst", 0, 100000},
        {"zstd/skewed_fast3.zst", 1, 100000},     {"zstd/skewed_l9_check.zst", 1, 100000},
        {"zstd/random_l3.zst", 2, 20000},         {"zstd/runs_l3_check.zst", 3, 200000},
        {"zstd/empty_l3.zst", 0, 0},
    };
    for (const Case &c : cases) {
        std::string in = ReadFile(Fixture(c.file));
        std::string out, err;
        bool ok = Decode(in, &out, &err);
        if (!ok || out != MakeZstdTestData(c.kind, c.size)) {
            std::fprintf(stderr, "zstd fixture %s: ok=%d size=%zu err=%s\n", c.file, ok, out.size(), err.c_str());
        }
        CHECK(!in.empty());
        CHECK(ok);
        CHECK(out == MakeZstdTestData(c.kind, c.size));
    }

    // Several frames plus a skippable frame in between (Blender writes its
    // seek table as a trailing skippable frame).
    std::string a = ReadFile(Fixture("zstd/text_l1.zst"));
    std::string b = ReadFile(Fixture("zstd/skewed_l9_check.zst"));
    std::string skippable = std::string("\x50\x2a\x4d\x18\x03\x00\x00\x00xyz", 11);
    std::string out;
    CHECK(Decode(a + skippable + b, &out));
    CHECK(out == MakeZstdTestData(0, 100000) + MakeZstdTestData(1, 100000));

    // Corruption is reported, never crashes.
    std::string bad = ReadFile(Fixture("zstd/text_l19_check.zst"));
    bad[bad.size() / 2] = static_cast<char>(bad[bad.size() / 2] ^ 0x5A);
    CHECK(!Decode(bad, &out));
    std::string truncated = a.substr(0, a.size() / 2);
    CHECK(!Decode(truncated, &out));
    CHECK(!Decode("not zstd at all", &out));
    CHECK(!zstd::LooksLikeZstd(reinterpret_cast<const unsigned char *>("BLENDER"), 7));
    CHECK(zstd::LooksLikeZstd(reinterpret_cast<const unsigned char *>(a.data()), a.size()));
    // Size limit (decompression-bomb guard).
    std::string limited;
    std::string runs = ReadFile(Fixture("zstd/runs_l3_check.zst"));
    CHECK(!zstd::Decompress(reinterpret_cast<const unsigned char *>(runs.data()), runs.size(), limited, nullptr, 1000));
}

struct Box {
    float lo[3] = {1e30f, 1e30f, 1e30f};
    float hi[3] = {-1e30f, -1e30f, -1e30f};
    float Center(int axis) const { return 0.5f * (lo[axis] + hi[axis]); }
    float Size(int axis) const { return hi[axis] - lo[axis]; }
};

Box BoundsOf(const blend::ScenePart &p) {
    Box b;
    for (size_t i = 0; i < p.positions.size(); i++) {
        b.lo[i % 3] = std::min(b.lo[i % 3], p.positions[i]);
        b.hi[i % 3] = std::max(b.hi[i % 3], p.positions[i]);
    }
    return b;
}

bool Near(float a, float b, float eps = 1e-3f) { return std::fabs(a - b) <= eps; }

const blend::ScenePart *FindPart(const blend::Scene &s, const std::string &name) {
    for (const blend::ScenePart &p : s.parts) {
        if (p.name == name) return &p;
    }
    return nullptr;
}

bool CenterIs(const blend::Scene &s, const std::string &name, float x, float y, float z) {
    const blend::ScenePart *p = FindPart(s, name);
    if (!p) {
        std::fprintf(stderr, "missing part %s\n", name.c_str());
        return false;
    }
    Box b = BoundsOf(*p);
    bool ok = Near(b.Center(0), x) && Near(b.Center(1), y) && Near(b.Center(2), z);
    if (!ok) {
        std::fprintf(stderr, "part %s center (%g %g %g), want (%g %g %g)\n", name.c_str(), static_cast<double>(b.Center(0)),
                     static_cast<double>(b.Center(1)), static_cast<double>(b.Center(2)), static_cast<double>(x),
                     static_cast<double>(y), static_cast<double>(z));
    }
    return ok;
}

// Structural invariants every extracted part must satisfy.
void CheckPartInvariants(const blend::ScenePart &p) {
    size_t nv = p.positions.size() / 3;
    CHECK(p.positions.size() % 3 == 0);
    CHECK(p.normals.size() == p.positions.size());
    CHECK(p.texcoords.empty() || p.texcoords.size() == nv * 2);
    CHECK(!p.indices.empty() && p.indices.size() % 3 == 0);
    bool in_range = true, unit = true;
    for (unsigned int i : p.indices) in_range = in_range && i < nv;
    for (size_t v = 0; v < nv; v++) {
        float x = p.normals[v * 3], y = p.normals[v * 3 + 1], z = p.normals[v * 3 + 2];
        unit = unit && Near(std::sqrt(x * x + y * y + z * z), 1.0f, 1e-3f);
    }
    CHECK(in_range);
    CHECK(unit);
}

// For a closed convex part (a cube): every triangle winds counter-clockwise
// seen from outside, and agrees with its vertex normals.
bool OutwardWinding(const blend::ScenePart &p) {
    Box b = BoundsOf(p);
    float c[3] = {b.Center(0), b.Center(1), b.Center(2)};
    for (size_t t = 0; t + 2 < p.indices.size(); t += 3) {
        const float *a = &p.positions[p.indices[t] * 3];
        const float *q = &p.positions[p.indices[t + 1] * 3];
        const float *r = &p.positions[p.indices[t + 2] * 3];
        float u[3] = {q[0] - a[0], q[1] - a[1], q[2] - a[2]};
        float v[3] = {r[0] - a[0], r[1] - a[1], r[2] - a[2]};
        float n[3] = {u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]};
        float out[3] = {(a[0] + q[0] + r[0]) / 3 - c[0], (a[1] + q[1] + r[1]) / 3 - c[1], (a[2] + q[2] + r[2]) / 3 - c[2]};
        if (n[0] * out[0] + n[1] * out[1] + n[2] * out[2] <= 0) return false;
        const float *vn = &p.normals[p.indices[t] * 3];
        if (n[0] * vn[0] + n[1] * vn[1] + n[2] * vn[2] <= 0) return false;
    }
    return true;
}

bool HasWarning(const blend::Scene &s, const std::string &needle) {
    for (const std::string &w : s.warnings) {
        if (w.find(needle) != std::string::npos) return true;
    }
    return false;
}

const blend::SceneMaterial *MaterialOf(const blend::Scene &s, const std::string &part) {
    const blend::ScenePart *p = FindPart(s, part);
    if (!p || p->material < 0) return nullptr;
    return &s.materials[static_cast<size_t>(p->material)];
}

blend::Scene Load(const std::string &rel) {
    blend::Scene s;
    std::string err;
    bool ok = blend::ReadScene(Fixture(rel), &s, &err);
    if (!ok) std::fprintf(stderr, "%s: %s\n", rel.c_str(), err.c_str());
    CHECK(ok);
    for (const blend::ScenePart &p : s.parts) CheckPartInvariants(p);
    return s;
}

void TestBlender50() {
    // Blender 5.0: "BLENDER17-01v0502" header, 64-bit block headers,
    // Mesh.attribute_storage, Blender's own multi-frame zstd.
    blend::Scene s = Load("blend/cube_v502_zstd.blend");
    CHECK(s.version == 502);
    CHECK(s.compression == "zstd");
    CHECK(s.parts.size() == 1);
    if (!s.parts.empty()) {
        const blend::ScenePart &p = s.parts[0];
        CHECK(p.name == "Cube");
        CHECK(p.indices.size() == 36);
        CHECK(p.positions.size() == 24 * 3);  // flat-shaded: 4 corners per face
        CHECK(p.texcoords.size() == 24 * 2);
        Box b = BoundsOf(p);
        for (int k = 0; k < 3; k++) CHECK(Near(b.lo[k], -1.0f) && Near(b.hi[k], 1.0f));
        CHECK(OutwardWinding(p));
        bool uv_in_range = true;
        for (float t : p.texcoords) uv_in_range = uv_in_range && t >= -1e-4f && t <= 1.0001f;
        CHECK(uv_in_range);
    }
    CHECK(s.materials.size() == 1);
    if (!s.materials.empty()) CHECK(s.materials[0].name == "Material");
    CHECK(HasWarning(s, "Armature"));  // the cube has an Armature modifier, not applied

    // Several meshes whose per-ID data addresses collide (Blender 5.x writes
    // deterministic per-ID pointers), parenting, and smooth shading.
    blend::Scene h = Load("blend/hierarchy_v502_zstd.blend");
    CHECK(h.parts.size() == 9);
    CHECK(CenterIs(h, "Cube", 0, 0, 0));
    CHECK(CenterIs(h, "Cube.001", 0, -3, 0));
    CHECK(CenterIs(h, "Sphere", 0, 3, 0));
    CHECK(CenterIs(h, "Cylinder", -4, 0, 0));
    CHECK(CenterIs(h, "Cone", 0, 0, -7));
    CHECK(CenterIs(h, "Plane", 0, 0, -10));
    CHECK(CenterIs(h, "Suzanne.001", 0, 6, 0));
    CHECK(CenterIs(h, "Torus", 0, 0, 9));
    if (const blend::ScenePart *suz = FindPart(h, "Suzanne")) {
        CHECK(suz->indices.size() == 968 * 3);  // 500 faces: 468 quads + 32 triangles
    }
    CHECK(h.warnings.empty());
}

void TestBlender40() {
    // Blender 4.0: CustomData "position"/".corner_vert" attributes and
    // Mesh.poly_offset_indices; Principled BSDF inputs.
    blend::Scene s = Load("blend/custom_normals_v400_zstd.blend");
    CHECK(s.version == 400);
    CHECK(s.parts.size() == 1);
    if (const blend::ScenePart *p = FindPart(s, "SmoothCube")) CHECK(p->indices.size() == 44 * 3);
    const blend::SceneMaterial *m = MaterialOf(s, "SmoothCube");
    CHECK(m != nullptr);
    if (m) {
        CHECK(m->name == "Shiny");
        CHECK(Near(m->metallic, 1.0f));
        CHECK(Near(m->roughness, 0.0f));
    }
}

void TestBlender33() {
    // Blender 3.3: MVert/MPoly/MLoop/MLoopUV CustomData layers, object-
    // linked material slots, shared meshes.
    blend::Scene s = Load("blend/mesh_instances_v303_zstd.blend");
    CHECK(s.version == 303);
    CHECK(s.parts.size() == 8);
    CHECK(CenterIs(s, "original", 0, 0, 0));
    CHECK(CenterIs(s, "original_instance", 3, 0, 0));
    CHECK(CenterIs(s, "skined_2", 3, 0, 10));
    const blend::SceneMaterial *red = MaterialOf(s, "original");
    const blend::SceneMaterial *green = MaterialOf(s, "with_object_material");
    const blend::SceneMaterial *blue = MaterialOf(s, "with_object_material_other");
    CHECK(red && green && blue);
    if (red && green && blue) {
        CHECK(red->color[0] > 0.7f && red->color[1] < 0.1f);
        CHECK(green->color[1] > 0.7f && green->color[0] < 0.1f);
        CHECK(blue->color[2] > 0.7f && blue->color[0] < 0.1f);
    }
    CHECK(HasWarning(s, "modifier_1: modifiers not applied (Subdivision)"));
    for (const blend::ScenePart &p : s.parts) CHECK(!p.texcoords.empty());
}

void TestBlender279() {
    // Blender 2.79, gzip container: parents with Euler, quaternion,
    // axis-angle rotations, scale, and parent-inverse matrices.
    blend::Scene s = Load("blend/parent_inverse_v279_gzip.blend");
    CHECK(s.version == 279);
    CHECK(s.compression == "gzip");
    CHECK(s.parts.size() == 10);
    CHECK(CenterIs(s, "ParentLocation", -8, 0, 0));
    CHECK(CenterIs(s, "ChildLocation", -8, 4, 0));
    CHECK(CenterIs(s, "ParentQuaternion", 4, 0, 0));
    CHECK(CenterIs(s, "ChildQuaternion", 4, 4, 0));
    CHECK(CenterIs(s, "ParentAxisAngle", 8, 0, 0));
    CHECK(CenterIs(s, "ChildAxisAngle", 8, 4, 0));
    CHECK(CenterIs(s, "ChildScale", -4, 4, 0));
    if (const blend::ScenePart *p = FindPart(s, "ParentScale")) {
        Box b = BoundsOf(*p);
        CHECK(Near(b.Size(0), 1.0f) && Near(b.Size(1), 1.0f) && Near(b.Size(2), 1.0f));
    }
    if (const blend::ScenePart *p = FindPart(s, "ParentQuaternion")) {
        Box b = BoundsOf(*p);  // rotated 45 degrees about the vertical axis
        CHECK(Near(b.Size(0), 2.0f * std::sqrt(2.0f)) && Near(b.Size(1), 2.0f));
        CHECK(OutwardWinding(*p));
    }
}

void TestBlender248() {
    // Blender 2.48: 4-byte pointers, uncompressed, MFace tessellated faces,
    // Object.colbits, a deep parent chain.
    blend::Scene s = Load("blend/cube_hierarchy_v248_ptr4.blend");
    CHECK(s.version == 248);
    CHECK(s.compression.empty());
    CHECK(s.parts.size() == 11);
    CHECK(CenterIs(s, "Cube1", -2.582f, 0.216f, 0));
    CHECK(CenterIs(s, "Cube.008", 6.148f, 8.645f, 0));
    CHECK(CenterIs(s, "Cube.004", -11.371f, 8.572f, 0));
    if (const blend::ScenePart *p = FindPart(s, "Cube.004")) CHECK(OutwardWinding(*p));

    blend::Scene m = Load("blend/four_materials_v248_ptr4_zstd.blend");
    CHECK(m.parts.size() == 4);
    CHECK(m.materials.size() == 4);
    const blend::SceneMaterial *c3 = MaterialOf(m, "Cube.003");
    CHECK(c3 != nullptr);
    if (c3) {
        CHECK(Near(c3->color[0], 0.861f) && Near(c3->color[1], 0.048f) && Near(c3->color[2], 0.060f));
    }
}

void TestErrors() {
    blend::Scene s;
    std::string err;
    CHECK(!blend::ReadSceneFromBytes("hello world", "", &s, &err));
    CHECK(!err.empty());
    CHECK(!blend::ReadScene(Fixture("blend/does_not_exist.blend"), &s, &err));

    // Truncated and corrupted files fail cleanly (or still parse), never
    // crash -- run under the sanitizer build to make this meaningful.
    std::string raw = ReadFile(Fixture("blend/cube_hierarchy_v248_ptr4.blend"));
    CHECK(!blend::ReadSceneFromBytes(raw.substr(0, 11), "", &s, &err));
    uint32_t seed = 1;
    for (int i = 0; i < 60; i++) {
        std::string m = raw;
        seed = seed * 1664525u + 1013904223u;
        if (i % 3 == 0) {
            m.resize(seed % m.size());
        } else {
            for (int k = 0; k < 16; k++) {
                seed = seed * 1664525u + 1013904223u;
                m[(seed >> 4) % m.size()] = static_cast<char>(seed >> 24);
            }
        }
        blend::Scene t;
        blend::ReadSceneFromBytes(std::move(m), "", &t, &err);
    }
}

void TestSdna() {
    blend::File f;
    std::string err;
    CHECK(f.Load(Fixture("blend/cube_v502_zstd.blend"), &err));
    CHECK(f.format_version() == 1);
    CHECK(f.pointer_size() == 8);
    CHECK(!f.big_endian());
    const blend::Struct *ob = f.FindStruct("Object");
    CHECK(ob != nullptr);
    if (ob) {
        const blend::Field *loc = ob->Find("loc");
        CHECK(loc && loc->count == 3 && loc->is_float && loc->type == "float");
        const blend::Field *mat = ob->Find("mat");
        CHECK(mat && mat->pointer_depth == 2);
        const blend::Field *pinv = ob->Find("parentinv");
        CHECK(pinv && pinv->count == 16 && pinv->size == 64);
        CHECK(ob->is_id);
        // Field offsets add up to the struct size SDNA records.
        size_t sum = 0;
        for (const blend::Field &fd : ob->fields) sum += fd.size;
        CHECK(sum == ob->size);
    }
    blend::File old;
    CHECK(old.Load(Fixture("blend/cube_hierarchy_v248_ptr4.blend"), &err));
    CHECK(old.format_version() == 0);
    CHECK(old.pointer_size() == 4);
    const blend::Struct *ob4 = old.FindStruct("Object");
    CHECK(ob4 && ob4->Find("parent") && ob4->Find("parent")->size == 4);
}

}  // namespace

int main() {
    TestZstd();
    TestSdna();
    TestBlender50();
    TestBlender40();
    TestBlender33();
    TestBlender279();
    TestBlender248();
    TestErrors();
    if (g_failures) {
        std::fprintf(stderr, "%d check(s) failed\n", g_failures);
        return 1;
    }
    std::printf("blend import tests passed\n");
    return 0;
}
